using System;

namespace Practice
{
    class Program
    {
        static void Main(string[] args)
        {
            string s = (Console.ReadLine());
            Console.WriteLine(SolveProblem(s));
            Console.ReadLine();
        }

        static string SolveProblem (string s)
        {
            int lowerCount = 0;
            int higherCount = 0;
            for (int i = 0; i < s.Length ;i++)
            {
                if (char.IsLower( s [i]))
                {
                    lowerCount++;
                } else
                {
                    higherCount++;
                }

                if (lowerCount > (s.Length) / 2)
                {
                    return s.ToLower();
                }
            }
            return lowerCount == higherCount ? s.ToLower() :s.ToUpper();
        }

    }
}
